using Microsoft.Data.Sqlite; using Workbench.Core.Workers; using Workbench.Storage.Database;
namespace Workbench.Storage.Workers;
public sealed class PermissionRepository(WorkbenchDatabase database){private readonly WorkbenchDatabase _d=database; public async Task AddAsync(Guid project,Guid id,PermissionRequest p,CancellationToken ct=default){await using var c=_d.CreateConnection();await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="INSERT INTO permission_requests(id,task_id,revision_number,requested_capability,scope,access_mode,reason,risk,requested_duration_seconds,state,created_at) SELECT $i,$t,$n,$c,$s,$a,$r,$k,$d,'Pending',$at WHERE EXISTS(SELECT 1 FROM tasks WHERE id=$t AND project_id=$p)";q.Parameters.AddWithValue("$i",id.ToString());q.Parameters.AddWithValue("$p",project.ToString());q.Parameters.AddWithValue("$t",p.TaskId.ToString());q.Parameters.AddWithValue("$n",p.RevisionNumber);q.Parameters.AddWithValue("$c",p.RequestedCapability);q.Parameters.AddWithValue("$s",p.Scope);q.Parameters.AddWithValue("$a",p.AccessMode.ToString());q.Parameters.AddWithValue("$r",p.Reason);q.Parameters.AddWithValue("$k",p.Risk.ToString());q.Parameters.AddWithValue("$d",(long)p.RequestedDuration.TotalSeconds);q.Parameters.AddWithValue("$at",p.CreatedAt.ToString("O"));await q.ExecuteNonQueryAsync(ct);} public async Task<bool> ResolveAsync(Guid project,Guid task,Guid id,string decision,string decidedBy,CancellationToken ct=default){await using var c=_d.CreateConnection();await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="UPDATE permission_requests SET state=$d,decision=$d,decided_by=$b,decided_at=$a WHERE id=$i AND task_id=$t AND state='Pending' AND EXISTS(SELECT 1 FROM tasks WHERE id=$t AND project_id=$p)";q.Parameters.AddWithValue("$d",decision);q.Parameters.AddWithValue("$b",decidedBy);q.Parameters.AddWithValue("$a",DateTimeOffset.UtcNow.ToString("O"));q.Parameters.AddWithValue("$i",id.ToString());q.Parameters.AddWithValue("$t",task.ToString());q.Parameters.AddWithValue("$p",project.ToString());return await q.ExecuteNonQueryAsync(ct)==1;}}
